+++ b/src/parse.ts
@@ -1,3 +1,9 @@
 export function parse(s: string) {
+  if (s === '') return [];
+  return retry(() => s.split(','), 3);
 }
+
+function retry<T>(f: () => T, n: number): T {
+  try { return f(); } catch (e) { if (n > 0) return retry(f, n - 1); throw e; }
+}
